class Solution {
    public int knightDialer(int n) {
        int MOD = 1_000_000_007;
        int[][] moves = {
            {4, 6}, {6, 8}, {7, 9}, {4, 8}, {0, 3, 9},
            {}, {0, 1, 7}, {2, 6}, {1, 3}, {2, 4}
        };
        long[] dp = new long[10];
        Arrays.fill(dp, 1);
        for (int step = 1; step < n; step++) {
            long[] nextDp = new long[10];
            for (int curr = 0; curr < 10; curr++) {
                for (int nxt : moves[curr]) {
                    nextDp[nxt] = (nextDp[nxt] + dp[curr]) % MOD;
                }
            }
            dp = nextDp;
        }
        long total = 0;
        for (int i = 0; i < 10; i++) total = (total + dp[i]) % MOD;
        return (int) total;
    }
}

var knightDialer = function(n) {
    const MOD = 1000000007;
    const moves = [
        [4, 6], [6, 8], [7, 9], [4, 8], [0, 3, 9],
        [], [0, 1, 7], [2, 6], [1, 3], [2, 4]
    ];
    let dp = new Array(10).fill(1);
    for (let step = 1; step < n; step++) {
        const nextDp = new Array(10).fill(0);
        for (let curr = 0; curr < 10; curr++) {
            for (const nxt of moves[curr]) {
                nextDp[nxt] = (nextDp[nxt] + dp[curr]) % MOD;
            }
        }
        dp = nextDp;
    }
    return dp.reduce((acc, v) => (acc + v) % MOD, 0);
};
